) AS (
  VALUES 
    (109::BIGINT, 'Es demasiado exigente con las tareas simples, si sospecha que usaste IA te pone un 40, pero al final te asigna 3 tareas extra para que pases si haces las cosas'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'aae28336cd20c8e309db2176fd79ed56b12eb22eed1ede8556fe00c8cc9723fc'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'El curso es muy tedioso, pasable, pero tedioso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'fdd180e3747e52963f3bec3c5aedb7872be8dacb4d0b212fb3ba934ad12c840e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Pinche vieja no explica nada en clase, no explica como se tienen que hacer las tareas y envia las rubricas un dia antes de la entrega, malisima con el tec digital y deja dos proyectos al mismo tiempo para la misma fecha. Ademas califica durisimo las tareas. Lo unico bueno es que deja trabajos extra.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-02T00:00:00+00:00'::TIMESTAMPTZ, '6f22bc66589769ff11e5684e3a6ed13bf0e84667652d678bc618d32fdf98706f'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La verdad para ser un curso de relleno lo complica demasiado, la mitad del curso es hacer cálculos que ni ella sabe hacer, y si usted los hace con IA siempre se los da mal, no se sabe ni qué es lo que pide. Mejor meta con Hasbum que sí regala el curso'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'e163bb90dbc2cd2b4ce2c01e39e1a2da440104e16e4ac7b02ff991a345fdc28d'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Evite a toda costa llevar con ella, es buena gente pero desastre en todos los aspectos. Califica súper duro y pregunta cosas en el examen que ni están en clases, además, es muy desordenada y pasa cambiando los rubros del curso. Se pasa pero para ser un curso relleno si exige demasiado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'f7d1afa435225488cbd3e1d818a486af6061a85b93c3342482219c41a490b4e9'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ella es buena gente, pero su problema viene en el segundo examen. El primero y el tercero son de teoría que puedes ir repasando fácil, pero el segundo es sumamente cansado en donde que hay hacer MUCHOS cálculos que no nos importan para la carrera. Si pudiera llevarlo con otro, estaria mejor.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b2eecdbd30378a4180556120649a8ea71bc2cc170310dc0b9772546b1e14ff5f'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La verdad no tengo quejas, es fácil pasar con ella, solo que si es mejor leer un poco antes de los exámenes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8ca32feae9802ac8b5dd83302588948b5b493dc155082ce73ef841d62564c692'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Eato no es un curso es un rosario de filminas ... busquen otra profe o rewigense al aburrimiento'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'be6ff7188c9ba9c06b71766861fb1c4ff3116f8909e8d7fb144825b657553926'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6454461e5bd3d6e4f8eca73613ebbf69322b2e9c9a4b0b02676847c6f7fcabea'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe sabe mucho pero la calificación es un poco complicada, las clases virtuales son bastante cansadas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'eea50cf1fb7b7e617f502a139e3c5d5f4a5938b8682c6f25543e2d3b9ab3d2d9'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Haga las cosas y con eso pasa, lo unico esq es medio confuso la calificacion y porcentajes en el curso, si lleva un semestre pesado esta clase es muy pasajera no te quita tanto como otras generales'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'bcbb5aace2fb7d572483ea7f580e91bb1623f4df12355c787f92fb789bd1365b'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'No la recomiendo, la profe es buena nota y todo, pero al menos en virtual básicamente solo leía las presentaciones y casi ni hacía ejercicios de cálculos y tampoco dejaba mucha práctica para estos. Pero hay un examen que es puro cálculo entonces uno queda completamente bateado.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'ede64b4a1842b060ebfde57339d31702c77334f2beb8525de60ff1328324ac5c'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Habla de forma muy tecnica, pidan que les explique con ejemplos, los trabajos hay q hacerlos bien echos porque califica duro, hay q estudiar de verdad, algo muy bueno, ella se preocupa xq los estudiantes pasen, Si todos salen mal repite el examen, hace curva, da puntos. No es muy buena en calculos'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '2124637e0555aafd76d3b4ccaaf1e06b4b5ffa6ce1893d2001734236fb67d80e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profesora no tiene autoconfianza, eso hace que se enrede a la hora de hablar, llega tarde a propósito porque tiene pánico escénico, sus respuestas a las tareas no son correctas y siempre termina corrigiéndolas, lo cual hace que sea muy difícil entender la materia.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Exámenes retadores']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'edeed20c686f04dcfa3cee0307a3d83ab3c6aaf9bfa2f77e10ff1c90a2e5288e'::TEXT, ARRAY[288]::BIGINT[]),
    (109::BIGINT, 'Pésima profe, tiene dislexia al parecer entonces en los cálculos los hace mal, las respuestas las pone mal, entonces si uno la corrige enreda más de la cuenta a la clase, a pesar de que yo siempre tome nota de todo lo que decía en clase, el examen traia cosas muy distintas a lo que explicó, evitenla'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'c330b2a8d03e91fce730553594fc0ba1745f4d99a598c85ef08435d5b55b4891'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Es buena profe, las clases son un poco aburridas, pero deja la materia clara, un consejo importante con ella: apuntar las fechas de los entregables y tener respaldos, porque a veces se le olvida habilitarlas en el tecDigital'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '45fac8da25e7f9121cc31795d6e67146a15f4488cc16f4eb86de3ffa1eb523f5'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '24c41b177e22d808d5c70f55430e9a2d5f67bb1b00dc85d9f437f6d3c5474bff'::TEXT, ARRAY[288]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '3070db0e5275043c283c346fb3f6b28032a410f9860bc8b82e6c634b3895b19a'::TEXT, ARRAY[288]::BIGINT[]),
    (109::BIGINT, 'ES una prepotente, nunca acepta que se equivocó y busca la forma de quedar bien ella, los examenes son confusos son de marque con x pero solo dos opciones, cree que uno estudia para abogado y siempre hace un enredo con sacar calculos NO RECOMIENDO MATRICULAR CON ELLA'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-28T00:00:00+00:00'::TIMESTAMPTZ, '4393f5942b21312ba408689f4e208c11052c149a6534e332a7b643da9a87dcd1'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Es buena persona, y como profesora es bastante buena, realmente el curso es fácil pero si se confía lo pierde porque los exámenes llevan mucho cálculo los cuales son enredados(trate de no desviarse de lo que se pide), en términos generales el curso si aprendes a hacer los cálculos se vuelve bonito.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f84ab1b780aa9101a5d1b1510aaef136b29af9beff8f683f52a1a1b11559c5ae'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe sin dudas es un amor de persona. Si es cierto que las clases se vuelven muy largas y aburridas. Los exámenes son muy fáciles al igual que las tareas y demás; porque son básicamente lo de las presentaciones, los cálculos pueden ser un poco más enredados pero nada imposible. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a82691bf1fbc678449ad205ca1b28a89f90f6aacd280c93fcf3aa19218beda57'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Es buena persona, explica mucho hasta que quede claro y a veces es medio aburrido, deja unas tareas en grupo y los exámenes son muy fáciles. Es una buena opción para matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'a6cd07f183281bd14a34a54f88060e63059cac22327bae83aecb22525ecadf08'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Las clases son bastante interesantes si se pone atención. Los examenes teóricos salen de las presentaciones y el de cálculo si estudia a conciencia lo saca fácil. Tareas cortas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '5aca69518369e21fc0c8d6b0f03de92a305fbd0d48983acce14605e0e0c3317e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'El segundo examen es dificil, ella no logra explicar bien los cálculos. La clase es aburrida porque es ella leyendo una presentación pero las tareas no son tan complicadas y son en grupo. Los otros dos examenes son faciles, entonces si entrega todo y busca como hacer los calculos pasa el curso facil'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '34903c6fad50dd72fca2b5d42b1df3290917c8b0f474b2792cf0bd40e126591f'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe es buena, solo que es algo aburrida. El segundo examen si estuvo algo dificil, ya que ella no explico muy bien como hacer las operaciones. Estudie por su cuenta y metase al sistema judicial, porque hay cosas que no estan en las presentaciones. Pero en general es una buena profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-02-19T00:00:00+00:00'::TIMESTAMPTZ, '86f15a4fc884a8d34f9f44186390a9edf7db3e8703806894961a682bfba5b42f'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Muy buena profe, explica bastante bien, se preocupa por que uno entienda. Las clases se pueden hacer aburridas, pero al final de cada clase hace una actividad en grupo, por lo que es importante prestar atención.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a523dddad0b42feb92dcb850e24166ccfd26f81a7d2234f72a76177e1cccf0ab'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe es demasiado lindaa, es muy buena nota, se preocupa un montón que uno entienda y se puede pasar con una muy buena nota fácilmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'd9c2fadd72491fe81b6f4209d510a31dbe9f655435c0cbcccf2f6078f7b171f8'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Pues la profesora es muy buena nota, pero hay que ponerle atención y hacer preguntas, pues en el examen salen trampas y si uno no puso atención se fue en todas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'e9ea2143e9b59fcb3682fdc3a7d6515ce41053ffd80848545e5088b9702645da'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Todo es en grupo, y la gente suele ser super vaga, para el segundo examen no ayuda nada, es de puros cálculos y ella no hace ejemplos, entonces usted llega bateado, pero con todo lo demás bien, se pasa fácil!'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'cd224dcfc1e4575e421e92f3077263b9dae4524a9a1472707b2bf04d7ab0c0d5'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Es bastante fácil, pero todos los trabajos son en grupos entonces procure meterlo con gente conocida'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-12-15T00:00:00+00:00'::TIMESTAMPTZ, '0dff3941617af8bf260569beb3fdec69efb74f752367b64ef7fb89cb128d9886'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Los exámenes son ir a marcar lo de las diapositivas. Un dolor de bolas el asistente con las tareas. Demasiado fácil esta profe para llevar un curso que vale picha'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f33c564a61dce8708238f349f2585a6c5268490abb7945ae8f8c9da12306c352'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, '[Virtual] Se aprende mucho en el curso, la mae explica bien pero solo teoría, no cómo hacer los cálculos que es lo que entra en las tareas. Los exámenes y tareas son complicados y califica muy duro. Si puede, meta con otro.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '75e66d87afbc2da23b0e223dad69174bb24cd62734c5d08a93a29e5180d8c078'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ay Martita, el primer examen casi que solo lo resuelve un abogado, en el segundo la mitad de las preguntas tenían errores y en las tareas casi se hace al bateo, explica mucha teoría y cero cálculos, si puede matricular con otro profe, hágalo!'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '4bc776f54d3e343b583d361be0dd5aa47fcadf9543c6f4459c367d418effb74c'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La clases virtuales son largas pero se aprende bastante, deja varias tareas que ayudan mucho para los exámenes y califica normal'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'e27636bfa0c6a42a56e91b52622f645c262690691d0569128ed4d0c93925850c'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'En la clase si se aprende, pero las clases son terribles. Se pierde hablando de cualquier cosa si alguien le da cuerda puede perder horas, el primer examen es como para abogados. Si les interesa mucho el derecho y quieren meterle muchas horas al curso, metalo con ella. Muchas horas, pocos creditos.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1ca910b4aacf73b50c65b0d4f70e48bacc851f63c68f07dea04b6f69847fc357'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'No explica bien la parte de cálculos y confunde mucho. Muy prepotente a la hora de aclarar dudas, no matricularía con ella un curso de nuevo'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'a2e607e4ea0aa226b07d06b4d7c961936299d32ed38af793fa0483329a2ed62a'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Tenía buenas expectativas con el curso y la profesora, pero en realidad no se cumplieron. Tal vez la modalidad virtual no le favoreció porque las clases dejaron de ser claras. Además se complica mucho para cálculos sencillos. Las calificaciones confusas. Buscaría otra opción mejor para aprender.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, '019283efcac1f08ef182e0e38cf44e31cac95beb758d3ce51a22e51ec4111ad9'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'e8a3b48f0b54a6bff33c3210012c5a9de8a7c756721ca7d2568573c7aabe6823'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, '96a1bf7df549ae1282d7ca8f160af3794fccfdce2cb00496c31eb04b47432d24'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Da el curso como para estudiantes de Derecho, le gusta lo que hace y se nota pero se pasa con los trabajos que pide, los exámenes no son fáciles y es muy poco atenta, complica demasiado un curso que se debería pasar fácil.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-07-03T00:00:00+00:00'::TIMESTAMPTZ, '9129cbd540c5f24426ee634cce2f5d045cfe87b2bb8cdd42ca71e5d74ad2387d'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Pros: Muy buena persona Ayuda a aquel que le cueste el curso sin embargo tiene que mostrar que lo intenta. Trata de ayudar al alumno lo más que pueda. Cons: Llega tarde a todas las clases. Su clase se basa en presentaciones. Su manera de hablar da sueño. Evaluaciones muy duras.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-02-07T00:00:00+00:00'::TIMESTAMPTZ, '7171b2820d5d15f0837d946c8259020b1c45971c03c6d089f9710eab1cfb7013'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'El curso no me interesaba mucho, pero lo hizo muy ameno. Con ir a las prácticas uno queda listo para el examen. Excelente profesora, súper recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-01-27T00:00:00+00:00'::TIMESTAMPTZ, '3cba8464ec511583760f4ffc93e1d05e3d85f5886e81cb6b7d855361d279376e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'El curso es aburrido, con ella se vuelve más aburrido incluso... No entiendo como un curso que no debería costar casi, hace que la mitad del grupo mame los exámenes...'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-10T00:00:00+00:00'::TIMESTAMPTZ, '36c73d48423e4e0bb7a23d4afb47ac4586f848d6b8ab2bb509be379df62c5509'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Explica bien pero no usa apoyo visual, solo lo que ella dice en clase (qué es prácticamente lo que viene en el examen). Explica muy rápido y tiene una voz muy chillona. Al final del curso si ve que le puso tal vez le pueda ayudar, la participación importa muchísimo. Ah y siempre llega tarde'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c3b6905b99253c5e53614acace9c340cce27d5150c917f909df85926d0f9adc8'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Es muy buena, maneja bien los temas y no es aburrida. Deja práctica que ayuda muchos para los exámenes. El problema es que no da instrucciones claras para los trabajos, a veces ni si quiera avisa que hay, solo lo pone en el TEC Digital sin notificar. Siempre llega tarde.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4f63bad68a8b8b8e5e983b8838bc75c1e5d959a88b797d4cc3a83f54347d7927'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Tiene muchos conocimientos y los brinda adecuadamente. Hay que prestar mucha atención porque si no es fácil perderse por completo. Nunca está presente el día del examen, cosa que da desventaja pues no hay a quién consultar durante la prueba.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9df65907888b1013bdea006f343b4c77dd54104b4c979e02b4c9c07ffcaf6718'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe es muy buena, se llega aprender mucho. Aunque es poco desordenada con las clases y los exámenes son fáciles solo debe tener cuidado con los conceptos. Los exámenes valen mucho, si quiere pasar relajado, saque bueno en los exámenes (medios fáciles) y en los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '47bd1c783b1d1c064069e1112c7b93c87645c79abf18819fd2cff64eaa8a007c'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'El curso en sí es sencillo. La profe hace la clase muy amena y explica muy bien, pero es un poco desordenada. Es muy comprensiva y le va a explicar 100 veces si es necesario para que usted entienda.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '53d5faff935d18072588fca6394cad5beda218ca70e70ee17f47671c2b8c7148'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Muy buena profe sabe mucho, explica bien y antes de los examenes deja practicas muy buenas que ayudan mucho para el examen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'a3129df5f5fba49d0fd4d8bfd82f083b464734a09e7edab983ee1dc000cc499e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'La profe es buena y sabe muchísimo del tema. El problema es que es súper desordenada, casi siempre llega tarde y si la clase termina mucho más tarde de lo que debería porque la alarga a propósito. Casi ni fa instrucciones para los trabajos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-05-15T00:00:00+00:00'::TIMESTAMPTZ, '35a75778ca2d7addde5b08cbe1431de1fd08b5e33c602cb579c8e27c40e87df8'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Muy fácil, el único detalle es que se enreda mucho y es desorganizada, califica suave y las dudas las explica hasta que uno entienda bien. Es fácil eximirse del examen final de cátedra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '1ee79c4526886f14ed5cccb40bc8de0f9f0f78575d4480409d563ea9936a29d6'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'El curso en si esta desorganizado, pero es una de las mejores en cuestión de facilidad. El trabajo escrito lo califica duro y los exámenes normal. Hace el curso integrante y si se llaga a aprender.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '204b7a42cfe1604bfcd3ea766efb074a0b40147d0b6e26ce813afa490de73c1a'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'No hace el curso pesado pero es un poco desorganizada con las clases. Es muy buena gente y le interesa que el estudiante aprenda. Siempre responde las dudas y no hace que la asistencia sea obligatoria.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1eebab2b51adae96530d41510a7c88388b81ea6a563fa2b0190e8b59a31d9def'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Tiene la voz muy chillona y habla mucho de su esposo (el gor) pero es fácil'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-11-03T00:00:00+00:00'::TIMESTAMPTZ, '01379556e8e7c0632db7b2b7d81fe6367d51b08387b537e1d3dadc4dd98962aa'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Los exámenes son super fáciles, nunca da las horas completas de las lecciones, siempre se sale antes, explica bien pero algunas veces da sueño.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1a12d008db782e8085c09c004c9d8ed8b6a652d4a59344adc3f5e6280174d496'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Yo sé que el curso es importante, pero ella hace que el curso valga mucho mas que 2 créditos. Explica muy bien la materia y sin duda le ayuda. Honestamente si quiere que el curso sea liviano NO meta con ella. (además tiene una voz bastante irritante)'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-17T00:00:00+00:00'::TIMESTAMPTZ, '722eca2e069514bb5bb091abb77da3b08ed30f4d803e48db6d2c5e4d356fce60'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Excelente Profesora, examenes faciles y califica suave en los examenes practicos, permite eximirse y da puntos extra por ir a las charlas o foros que ella organiza, dura un poco dando evaluaciones porque es la directora de la escuela'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-18T00:00:00+00:00'::TIMESTAMPTZ, '9f720ea6e63228a1c2092e736518bff01cda19ae95b04c2bf9c7b1fe75423961'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Excelente como persona y como profesora, explica muy bien, no es de asistencia obligatoria y tiene un carisma increible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b0e8a7a536d32c6d3c26a028fc190deb72043d969e0fe94370c7a665c918dbec'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Un amor de profe! Se aprende, y las evaluaciones son accesibles..'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd38055d9f506503b9029224e6033351244b4e5c605a5fb7f10ebfa83efa9076c'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Recomendada 100%!! Explica muy bien, las veces que sea necesario! Examenes muy accesibles!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '9cc10ac083eaa77a133b11391e5183f45ebd1614da7c812aff7ed2dba2fcd92f'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Excelente profesora, ayuda mucho con tareas extras, y no sigue la clase hasta que todos entiendan, una profe completamente recomendable'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'a854575b22738981d4ab186540078b442d583a3e674cd456cec2a09ab8308c3e'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Super buena profesora ! Y califica justo pero ayuda bastante y explica y explica y si no entiende explica de nuevo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '68760455aeb88da824a6ff4f421856037273ea9bd5cee1e3844558137a16e867'::TEXT, ARRAY[629]::BIGINT[]),
    (109::BIGINT, 'Excelente profesora'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '9912f3a4ef4b9b3675431ad4788883ff958d2eaafcc3e933463bf35a427eb8e2'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Es una buena profesora, explica bien, si no entiende ella se devuelve y le explica. Con los trabajos (tareas y proyectos) es muy facil sacar buena nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '84a602e443897cc6625954b22e45f66179ff8efe206a98f12ff940097a62873d'::TEXT, ARRAY[2445]::BIGINT[]),
    (109::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-27T00:00:00+00:00'::TIMESTAMPTZ, '388c7bf69ca010a6bf9b6f9e0c7ca202823f0304068954fe7288a7d8d374d343'::TEXT, ARRAY[2445]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
